"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["64589"],{64127(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_incompleto","status":422,"titulo":"Modalidade com remanejamento CRUZADO exige o par"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_incompleto","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada declarou `regraRemanejamento: CRUZADO` sem\\ndeclarar `remanejamentoPar`. Diferente de `DESTINO_UNICO` (ver\\n[`remanejamento_destino_obrigatorio`](/erros/uniplus.selecao.modalidade_selecionada.remanejamento_destino_obrigatorio)),\\nque precisa de um \xfanico destino, `CRUZADO` \xe9 o remanejamento rec\xedproco entre\\nduas modalidades (ex.: `AC_I`\u2194`AC_Q`, no processo seletivo ind\xedgena e\\nquilombola): a vaga que sobra numa migra para a outra. O **par** \xe9 a outra\\nmodalidade do cruzamento, e sem ele n\xe3o h\xe1 o que cruzar.","No documento publicado, o `remanejamentoDestinoFinal` \u2014 para onde a vaga vai quando nem a modalidade nem\\no par tiverem candidato aprovado \u2014 \xe9 **opcional**, e a aus\xeancia dele \xe9 uma\\ndeclara\xe7\xe3o, n\xe3o uma omiss\xe3o: o par n\xe3o tem destino final, e a vaga que\\nnenhuma das duas modalidades preencher permanece ociosa. \xc9 o caso do certame\\nisolado, que n\xe3o oferta ampla concorr\xeancia para receber essa sobra. Declarar\\n`remanejamentoDestinoFinal` sem `regraRemanejamento: CRUZADO`, esse sim, \xe9\\nrecusado \u2014 por\\n[`remanejamento_cruzado_indevido`](/erros/uniplus.selecao.modalidade_selecionada.remanejamento_cruzado_indevido).","Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**Os campos do documento publicado `regraRemanejamento`, `remanejamentoPar` e\\n`remanejamentoDestinoFinal` n\xe3o v\xeam\\ndo corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do\\ncadastro de modalidades de Configura\xe7\xe3o, no momento em que a modalidade \xe9\\nselecionada. No cadastro, esses campos s\xe3o `remanejamento.regra`,\\n`remanejamento.par` e `remanejamento.fallback`. O pr\xf3prio cadastro j\xe1 impede esta\\nincoer\xeancia na escrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela\\ndefini\xe7\xe3o de distribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade\\nestiver gravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo.","Enquanto houver a recusa de [cota reservada fora da ordem legal](/erros/uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata), os par\xe2metros do remanejamento n\xe3o s\xe3o conferidos. Corrija primeiro a cota para que essa confer\xeancia aconte\xe7a."],"comoResolver":["O campo que falta n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade\\ncadastrada em Configura\xe7\xe3o. Corrija l\xe1 o v\xednculo entre\\n`remanejamento.regra: CRUZADO` e o par, ou investigue como a modalidade foi\\ngravada sem essa coer\xeancia.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);